(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-637":{scenario:{company:"Hồng Lĩnh Project Management",supervisor:{name:"Doãn Quốc Hiếu",role:{vi:"Giám đốc quản lý dự án",en:"Project Management Director"}},ref_code:"PMR-0825",title:{vi:"Báo cáo thật. Đường găng rõ. Phục hồi có kế hoạch.",en:"True reporting. Clear critical path. Planned recovery."},brief:{vi:"Bạn lập báo cáo tháng PMR-0825 của dự án trường học có ngân sách hoàn thành BAC = 48 000 triệu đồng. Đến cuối kỳ: giá trị kế hoạch PV = 22 500, giá trị thu được EV = 18 000, chi phí thực tế AC = 19 200 (triệu đồng). Phần tiến độ còn lại có ba chuỗi công việc song song. Bản nháp chọn sai đường găng và dự báo chi phí hoàn thành như thể phần còn lại đúng ngân sách. Hãy sửa đường găng và EAC (triệu đồng), rồi lập báo cáo có căn cứ.",en:"You are preparing monthly report PMR-0825 for a school project with a budget at completion BAC = 48,000 million VND. At period end: planned value PV = 22,500, earned value EV = 18,000, actual cost AC = 19,200 (million VND). The remaining schedule has three parallel chains. The draft picks the wrong critical path and forecasts cost at completion as if the rest ran on budget. Correct the critical path and the EAC (million VND), then write an evidence-based report."},reference_title:{vi:"Mạng tiến độ cập nhật & bảng giá trị thu được đã duyệt",en:"Updated schedule network & approved earned value sheet"},fields:[{id:"CRIT_PATH",label:{vi:"Đường găng của tiến độ còn lại",en:"Critical path of the remaining schedule"},initial:"A-B-E-H",expected:"A-C-F-H",choices:["A-B-E-H","A-C-F-H","A-D-G-H"],reference:"Mạng tiến độ cập nhật",ref_value:{vi:"Thời gian (tuần): A 3; B 5, E 4; C 6, F 5; D 4, G 4; H 2; mỗi chuỗi đi từ A đến H",en:"Durations (weeks): A 3; B 5, E 4; C 6, F 5; D 4, G 4; H 2; every chain runs from A to H"},hint:{vi:"Đường găng là chuỗi có tổng thời gian dài nhất, không phải chuỗi chứa hạng mục lớn nhất.",en:"The critical path is the chain with the longest total duration, not the one with the biggest work item."}},{id:"EAC_M",label:{vi:"Dự báo chi phí hoàn thành EAC (triệu đồng)",en:"Estimate at completion EAC (million VND)"},initial:"49200",expected:"51200",reference:"Bảng giá trị thu được tháng 8",ref_value:{vi:"BAC 48 000; PV 22 500; EV 18 000; AC 19 200 (triệu đồng)",en:"BAC 48,000; PV 22,500; EV 18,000; AC 19,200 (million VND)"},hint:{vi:"Bản nháp dùng EAC = AC + (BAC - EV), chỉ đúng khi sai lệch chi phí là ngẫu nhiên và không lặp lại.",en:"The draft used EAC = AC + (BAC - EV), valid only when the cost variance is a one-off."}}],sop32:{vi:"CPI = EV / AC; SPI = EV / PV. Khi hiệu suất chi phí hiện tại được dự báo tiếp diễn: EAC = BAC / CPI; VAC = BAC - EAC. Ghi EAC đến triệu đồng.",en:"CPI = EV / AC; SPI = EV / PV. When current cost performance is expected to continue: EAC = BAC / CPI; VAC = BAC - EAC. State EAC to the nearest million VND."},context:{label:"PMIS / PMR-0825",metrics:[{label:{vi:"Ngân sách BAC (triệu đồng)",en:"Budget BAC (million VND)"},value:"48,000"},{label:{vi:"Giá trị thu được EV",en:"Earned value EV"},value:"18,000"},{label:{vi:"Chi phí thực tế AC",en:"Actual cost AC"},value:"19,200"}]},crisis:{vi:"Chủ đầu tư nhắn: “Báo cáo gửi ngân hàng tuần này phải ghi SPI = 1,0 và chi phí trong ngân sách, không thì đợt giải ngân bị treo. Số liệu thật để nội bộ biết thôi.”",en:"The owner texts: “The report to the bank this week must show SPI = 1.0 and cost on budget, or the next drawdown is frozen. Keep the real numbers internal.”"},options:{safe:{vi:"Báo cáo đúng SPI, CPI và EAC; báo giám đốc quản lý dự án, kèm kế hoạch phục hồi tiến độ (tăng ca, thi công song song có kiểm soát) và chi phí dự kiến để chủ đầu tư làm việc minh bạch với ngân hàng.",en:"Report the true SPI, CPI and EAC; inform the PM director and attach a recovery plan (overtime, controlled fast-tracking) with its cost so the owner can deal transparently with the bank."},shortcut:{vi:"Gửi ngân hàng bản báo cáo ghi SPI = 1,0 như yêu cầu, giữ số liệu thật trong nội bộ.",en:"Send the bank a report showing SPI = 1.0 as asked and keep the real figures internal."},wait:{vi:"Không gửi báo cáo nào và chờ chủ đầu tư tự làm việc với ngân hàng.",en:"Send no report and wait for the owner to handle the bank alone."}},questions:{vi:["Trình bày cách bạn xác định đường găng và tính CPI, SPI, EAC; các chỉ số này nói gì về sức khỏe dự án?","Báo cáo sai số liệu cho bên cho vay gây rủi ro pháp lý gì? Bạn đề xuất kế hoạch phục hồi tiến độ và chi phí như thế nào?"],en:["Explain how you identified the critical path and computed CPI, SPI and EAC; what do they say about project health?","What legal risks arise from misreporting to a lender? Which schedule and cost recovery plan would you propose?"]},hints:{vi:["Cộng tổng thời gian của từng chuỗi công việc trong mạng tiến độ trước khi chọn đường găng.","Theo SOP mục 3.2, tính CPI từ EV và AC rồi mới dự báo EAC từ ngân sách hoàn thành.","SOP mục 4.2: báo cáo cho bên ngoài phải trung thực; áp lực sửa số liệu phải báo giám đốc quản lý dự án."],en:["Add up the total duration of each chain in the network before choosing the critical path.","Under SOP 3.2, compute CPI from EV and AC before forecasting EAC from the budget at completion.","SOP 4.2: external reports must be truthful; escalate any pressure to alter figures to the PM director."]}},learning:{summary:{vi:"Quản lý dự án xây dựng lập kế hoạch, tổ chức và kiểm soát phạm vi, tiến độ, chi phí, chất lượng, an toàn và rủi ro của dự án từ chuẩn bị đầu tư đến bàn giao. Họ điều phối chủ đầu tư, tư vấn, nhà thầu và cơ quan quản lý, ra quyết định dựa trên số liệu và bảo đảm tuân thủ pháp luật. Nghề đòi hỏi kỹ năng lãnh đạo, giao tiếp, phân tích tiến độ, chi phí và sự chính trực trong báo cáo.",en:"A construction project manager plans, organizes and controls scope, schedule, cost, quality, safety and risk from project preparation to handover. They coordinate the owner, consultants, contractors and authorities, decide on evidence and ensure legal compliance. The role demands leadership, communication, schedule and cost analysis and integrity in reporting."},responsibilities:{vi:["Lập kế hoạch tổng thể, cấu trúc phân chia công việc (WBS) và tiến độ cơ sở của dự án.","Kiểm soát tiến độ, chi phí bằng phương pháp đường găng và giá trị thu được.","Quản lý hợp đồng, phối hợp các bên và giải quyết vướng mắc tại công trường.","Quản lý rủi ro, an toàn, chất lượng và yêu cầu thay đổi theo quy trình phê duyệt.","Báo cáo định kỳ cho chủ đầu tư, bên cho vay và tổ chức bàn giao, quyết toán."],en:["Build the master plan, work breakdown structure (WBS) and baseline schedule.","Control schedule and cost with critical path and earned value methods.","Manage contracts, coordinate parties and resolve site issues.","Manage risk, safety, quality and change requests through approval workflows.","Report regularly to the owner and lenders and organize handover and final accounts."]},competencies:[{name:{vi:"Lập & kiểm soát tiến độ",en:"Scheduling & control"},desc:{vi:"Xây dựng mạng CPM, xác định đường găng, thời gian dự trữ và kế hoạch phục hồi.",en:"Build CPM networks, identify the critical path and float and plan recovery."}},{name:{vi:"Quản lý chi phí",en:"Cost management"},desc:{vi:"Áp dụng EVM, dự báo EAC và kiểm soát dòng tiền dự án.",en:"Apply EVM, forecast EAC and control project cash flow."}},{name:{vi:"Lãnh đạo & điều phối",en:"Leadership & coordination"},desc:{vi:"Dẫn dắt nhóm nhiều bên, điều hành họp hiệu quả và ra quyết định kịp thời.",en:"Lead multi-party teams, run effective meetings and decide on time."}},{name:{vi:"Quản lý rủi ro",en:"Risk management"},desc:{vi:"Nhận diện, đánh giá và lập kế hoạch ứng phó rủi ro kỹ thuật, tài chính, pháp lý.",en:"Identify, assess and plan responses to technical, financial and legal risks."}},{name:{vi:"Chính trực",en:"Integrity"},desc:{vi:"Báo cáo trung thực với chủ đầu tư, bên cho vay và cơ quan quản lý.",en:"Report truthfully to owners, lenders and authorities."}}],knowledge:{vi:["Các nghị định hiện hành về quản lý dự án đầu tư xây dựng, chất lượng công trình và hợp đồng xây dựng.","Luật Đấu thầu số 22/2023/QH15 về lựa chọn nhà thầu cho dự án sử dụng vốn nhà nước.","PMBOK Guide của PMI: nguyên tắc và lĩnh vực hiệu suất quản lý dự án.","ISO 21502:2020 - Hướng dẫn quản lý dự án.","Phương pháp đường găng (CPM) và quản lý giá trị thu được (EVM): PV, EV, AC, CPI, SPI, EAC."],en:["Current decrees on construction project management, quality of works and construction contracts.","Procurement Law No. 22/2023/QH15 on contractor selection for state-funded projects.","PMI's PMBOK Guide: project management principles and performance domains.","ISO 21502:2020 - Guidance on project management.","Critical path method (CPM) and earned value management (EVM): PV, EV, AC, CPI, SPI, EAC."]},tools:["Phần mềm lập tiến độ CPM","Hệ thống thông tin quản lý dự án (PMIS)","Bảng tính EVM","Mô hình BIM 4D, 5D","Hệ thống văn bản và phê duyệt điện tử"],kpis:{vi:["SPI và CPI của dự án (mục tiêu từ 0,95 trở lên).","Tỷ lệ mốc tiến độ chính hoàn thành đúng hạn.","Số tai nạn lao động có ngày nghỉ (mục tiêu bằng 0).","Chênh lệch giữa EAC và ngân sách được duyệt."],en:["Project SPI and CPI (target 0.95 or above).","Share of key milestones achieved on time.","Lost-time injuries (target zero).","Variance between EAC and the approved budget."]},day:[{time:"07:30",vi:"Đọc báo cáo ngày của công trường, cảnh báo an toàn và tồn tại chất lượng.",en:"Read the site daily report, safety alerts and open quality issues."},{time:"09:00",vi:"Chủ trì giao ban tuần với tư vấn và nhà thầu về tiến độ, đường găng và nguồn lực.",en:"Chair the weekly meeting with consultants and contractors on progress, critical path and resources."},{time:"11:00",vi:"Cập nhật tiến độ thực tế, tính SPI, CPI và dự báo EAC.",en:"Update actual progress, compute SPI and CPI and forecast EAC."},{time:"14:00",vi:"Làm việc với chủ đầu tư về yêu cầu thay đổi và kế hoạch giải ngân.",en:"Meet the owner on change requests and the drawdown plan."},{time:"16:30",vi:"Duyệt kế hoạch phục hồi, ký văn bản và cập nhật sổ đăng ký rủi ro.",en:"Approve the recovery plan, sign correspondence and update the risk register."}],mistakes:{vi:["Chọn đường găng theo cảm tính hoặc theo hạng mục lớn, không tính tổng thời gian.","Dự báo EAC giả định phần còn lại đúng ngân sách trong khi vượt chi có tính hệ thống.","Làm đẹp số liệu báo cáo cho chủ đầu tư, bên cho vay thay vì đưa ra kế hoạch phục hồi."],en:["Choosing the critical path by instinct or by the biggest item without summing durations.","Forecasting EAC as if the rest runs on budget when overspending is systematic.","Dressing up figures for owners or lenders instead of presenting a recovery plan."]},career:[{vi:"Kỹ sư kế hoạch dự án",en:"Project planning engineer"},{vi:"Phó quản lý dự án",en:"Deputy project manager"},{vi:"Quản lý dự án xây dựng",en:"Construction project manager"},{vi:"Giám đốc dự án, giám đốc chương trình",en:"Project director, programme director"}],glossary:[{term:"Critical path",vi:"Chuỗi công việc dài nhất quyết định thời gian hoàn thành dự án; thời gian dự trữ bằng 0.",en:"Longest chain of activities setting the project finish date; it has zero float."},{term:"EVM",vi:"Quản lý giá trị thu được, so sánh PV, EV, AC để đo hiệu suất tiến độ và chi phí.",en:"Earned value management, comparing PV, EV and AC to measure schedule and cost performance."},{term:"CPI",vi:"Chỉ số hiệu suất chi phí bằng EV chia AC; nhỏ hơn 1 nghĩa là đang vượt chi.",en:"Cost performance index equal to EV divided by AC; below 1 means overspending."},{term:"Float",vi:"Thời gian dự trữ mà một công việc có thể chậm mà không làm chậm dự án.",en:"Time an activity can slip without delaying the project."},{term:"Fast-tracking",vi:"Thi công song song các công việc vốn tuần tự để rút ngắn tiến độ, chấp nhận rủi ro cao hơn.",en:"Overlapping activities normally done in sequence to shorten the schedule, accepting higher risk."}],quiz:[{q:{vi:"BAC = 10 000, EV = 4 000, AC = 5 000 (triệu đồng). Nếu hiệu suất chi phí hiện tại tiếp diễn, EAC là bao nhiêu?",en:"BAC = 10,000, EV = 4,000, AC = 5,000 (million VND). If current cost performance continues, what is the EAC?"},options:{vi:["11 000","10 000","12 500","9 000"],en:["11,000","10,000","12,500","9,000"]},answer:2,explain:{vi:"CPI = 4 000 / 5 000 = 0,8; EAC = 10 000 / 0,8 = 12 500 triệu đồng.",en:"CPI = 4,000 / 5,000 = 0.8; EAC = 10,000 / 0.8 = 12,500 million VND."}},{q:{vi:"SPI = 0,8 cho biết điều gì về dự án?",en:"What does SPI = 0.8 tell you about the project?"},options:{vi:["Dự án chậm tiến độ, mới đạt 80% giá trị kế hoạch","Dự án tiết kiệm 20% chi phí","Dự án vượt tiến độ 20%","Dự án đúng kế hoạch"],en:["Behind schedule, earning only 80% of planned value","20% under budget","20% ahead of schedule","Exactly on plan"]},answer:0,explain:{vi:"SPI = EV / PV; giá trị 0,8 nghĩa là khối lượng thực hiện mới bằng 80% kế hoạch.",en:"SPI = EV / PV; 0.8 means only 80% of the planned work has been earned."}},{q:{vi:"Chủ đầu tư yêu cầu báo cáo ngân hàng ghi SPI = 1,0 dù thực tế là 0,8. Bạn làm gì?",en:"The owner asks you to report SPI = 1.0 to the bank although it is 0.8. What do you do?"},options:{vi:["Ghi 1,0 cho kịp giải ngân","Ghi 0,9 cho trung hòa","Không gửi báo cáo nào","Báo cáo số thật, báo giám đốc và kèm kế hoạch phục hồi"],en:["Write 1.0 to secure the drawdown","Write 0.9 as a compromise","Send no report at all","Report the real figure, inform the director and attach a recovery plan"]},answer:3,explain:{vi:"Báo cáo sai cho bên cho vay là gian dối; cách đúng là minh bạch và chứng minh khả năng phục hồi.",en:"Misreporting to a lender is deception; the right path is transparency backed by a credible recovery plan."}},{q:{vi:"Công việc nằm trên đường găng có thời gian dự trữ (float) bằng bao nhiêu?",en:"How much float does an activity on the critical path have?"},options:{vi:["Bằng thời gian của chính nó","Bằng 0","Luôn bằng 1 tuần","Bằng tổng dự trữ của dự án"],en:["Equal to its own duration","Zero","Always one week","Equal to the project's total float"]},answer:1,explain:{vi:"Mọi chậm trễ trên đường găng đều làm chậm ngày hoàn thành nên thời gian dự trữ bằng 0.",en:"Any delay on the critical path delays completion, so its float is zero."}}],tools_en:["CPM scheduling software","Project management information system (PMIS)","EVM spreadsheet","4D and 5D BIM models","Electronic document and approval system"]}}})})(window.KKR);
